using System.ComponentModel.DataAnnotations;
using System.Security.Claims;
using EduSphere.Domain.Constants;
using EduSphere.Domain.Entities;
using EduSphere.Domain.Enums;
using EduSphere.Infrastructure;
using EduSphere.Web.Authorization;
using EduSphere.Web.Security;
using EduSphere.Web.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;
using Microsoft.EntityFrameworkCore;

namespace EduSphere.Web.Pages.Examinations;

[Authorize(Policy = AuthorizationPolicies.BranchAdmin)]
public sealed class DepthModel(TenantDbContext db, IBranchAccessService branchAccess, ExaminationDepthService service) : PageModel
{
    public IReadOnlyList<Exam> Exams { get; private set; } = []; public IReadOnlyList<ExamSchedule> Schedules { get; private set; } = []; public IReadOnlyList<StudentProfile> Students { get; private set; } = [];
    public IReadOnlyList<QuestionPaper> Papers { get; private set; } = []; public IReadOnlyList<QuestionPaperVersion> Versions { get; private set; } = []; public IReadOnlyList<ApplicationUser> Reviewers { get; private set; } = [];
    public IReadOnlyList<GradingScheme> Schemes { get; private set; } = []; public IReadOnlyList<MarkEntry> Marks { get; private set; } = []; public IReadOnlyList<MarksImportBatch> Imports { get; private set; } = [];
    public IReadOnlyList<ExamSeatingPlan> SeatingPlans { get; private set; } = []; public IReadOnlyList<ExamHallTicket> HallTickets { get; private set; } = []; public IReadOnlyList<ResultReviewRequest> Reviews { get; private set; } = [];
    public IReadOnlyList<ReportCardTemplate> Templates { get; private set; } = []; public IReadOnlyList<QuestionPaperReviewPolicy> Policies { get; private set; } = []; public IReadOnlyList<MarkingSchemeRelease> Releases { get; private set; } = [];
    public IReadOnlyList<ExamAttendanceRecord> Attendance { get; private set; } = []; public IReadOnlyList<ExamMalpracticeRecord> Malpractice { get; private set; } = []; public IReadOnlyList<ExternalGradingRule> ExternalRules { get; private set; } = [];
    public IReadOnlyList<MarkRubric> Rubrics { get; private set; } = []; public IReadOnlyList<MarkRubricCriterion> Criteria { get; private set; } = [];
    public IReadOnlyList<ResultComparisonRow> Comparisons { get; private set; } = [];
    [TempData] public string? Feedback { get; set; }
    [BindProperty] public SeatingInput Seating { get; set; } = new(); [BindProperty] public HallTicketInput HallTicketsInput { get; set; } = new(); [BindProperty] public RubricInput Rubric { get; set; } = new(); [BindProperty] public CriterionInput Criterion { get; set; } = new(); [BindProperty] public RubricScoreInput RubricScore { get; set; } = new();
    [BindProperty] public MarksImportInput MarksImport { get; set; } = new(); [BindProperty] public ReviewInput Review { get; set; } = new(); [BindProperty] public TemplateInput Template { get; set; } = new(); [BindProperty] public PolicyInput Policy { get; set; } = new(); [BindProperty] public ModerationInput Moderation { get; set; } = new(); [BindProperty] public ReleaseInput Release { get; set; } = new();
    [BindProperty] public AttendanceInput AttendanceInputModel { get; set; } = new(); [BindProperty] public MalpracticeInput MalpracticeInputModel { get; set; } = new(); [BindProperty] public ExternalRuleInput ExternalRule { get; set; } = new(); [BindProperty] public Guid? ComparisonStudentId { get; set; }

    public sealed class SeatingInput { [Required] public Guid? ExamScheduleId { get; set; } }
    public sealed class HallTicketInput { [Required] public Guid? ExamId { get; set; } }
    public sealed class RubricInput { [Required] public Guid? ExamScheduleId { get; set; } [Required, StringLength(150)] public string Name { get; set; } = "Assessment rubric"; }
    public sealed class CriterionInput { [Required] public Guid? MarkRubricId { get; set; } [Required, StringLength(200)] public string Name { get; set; } = ""; [Range(0.01,10000)] public decimal MaximumMarks { get; set; } [Range(1,100)] public int SortOrder { get; set; } = 1; }
    public sealed class RubricScoreInput { [Required] public Guid? MarkEntryId { get; set; } [Required] public Guid? CriterionId { get; set; } [Range(0,10000)] public decimal MarksAwarded { get; set; } [StringLength(500)] public string? Feedback { get; set; } }
    public sealed class MarksImportInput { [Required] public Guid? ExamScheduleId { get; set; } public IFormFile? File { get; set; } }
    public sealed class ReviewInput { [Required] public Guid? MarkEntryId { get; set; } public ResultReviewType Type { get; set; } [Required, StringLength(1000)] public string Reason { get; set; } = ""; }
    public sealed class TemplateInput { public Guid? BranchId { get; set; } public Guid? CourseId { get; set; } [Required, StringLength(120)] public string Name { get; set; } = "Standard report card"; [RegularExpression("^#[0-9A-Fa-f]{6}$")] public string PrimaryColor { get; set; } = "#135d66"; [StringLength(250)] public string? HeaderText { get; set; } [StringLength(500)] public string? FooterText { get; set; } public bool ShowRank { get; set; } = true; public bool ShowGradePoint { get; set; } = true; public bool ShowAttendance { get; set; } public bool IsDefault { get; set; } }
    public sealed class PolicyInput { public Guid? BranchId { get; set; } [Required, StringLength(120)] public string Name { get; set; } = "Two-reviewer approval"; [Range(1,10)] public int RequiredReviewerCount { get; set; } = 2; [Range(1,10)] public int RequiredApprovalCount { get; set; } = 2; public bool RejectOnAnyRejection { get; set; } = true; public bool IsDefault { get; set; } }
    public sealed class ModerationInput { [Required] public Guid? QuestionPaperId { get; set; } public ApprovalStatus Decision { get; set; } = ApprovalStatus.Approved; [StringLength(1000)] public string? Notes { get; set; } }
    public sealed class ReleaseInput { [Required] public Guid? QuestionPaperVersionId { get; set; } [Required] public Guid? ReleasedToUserId { get; set; } public DateTime ExpiresOn { get; set; } = DateTime.Now.AddDays(7); [StringLength(500)] public string? Notes { get; set; } }
    public sealed class AttendanceInput { [Required] public Guid? ExamScheduleId { get; set; } [Required] public Guid? StudentProfileId { get; set; } public ExamAttendanceStatus Status { get; set; } [StringLength(500)] public string? Notes { get; set; } }
    public sealed class MalpracticeInput { [Required] public Guid? ExamScheduleId { get; set; } [Required] public Guid? StudentProfileId { get; set; } public MalpracticeSeverity Severity { get; set; } [Required, StringLength(2000)] public string Description { get; set; } = ""; }
    public sealed class ExternalRuleInput { [Required] public Guid? GradingSchemeId { get; set; } [Required, StringLength(120)] public string AuthorityName { get; set; } = ""; [StringLength(50)] public string? AuthorityCode { get; set; } [Range(0,100)] public decimal MaximumGraceMarks { get; set; } [Range(0,100)] public decimal MaximumGracePercentage { get; set; } public bool GraceOnlyForPassing { get; set; } = true; public bool ApplyBestOfSubjects { get; set; } public int? BestOfSubjectCount { get; set; } }
    public sealed record ResultComparisonRow(string Exam, string AcademicYear, decimal Percentage, string? Grade, bool Passed, int? Rank);

    public async Task OnGetAsync(Guid? studentId) { ComparisonStudentId = studentId; await LoadAsync(); }
    public async Task<IActionResult> OnPostGenerateSeatingAsync() { if (!Seating.ExamScheduleId.HasValue) return RedirectToPage(); var plan = await service.GenerateSeatingPlanAsync(Seating.ExamScheduleId.Value, UserId(), default); Feedback = $"Generated {plan.CandidateCount} seat assignments."; return RedirectToPage(); }
    public async Task<IActionResult> OnPostGenerateTicketsAsync() { if (!HallTicketsInput.ExamId.HasValue) return RedirectToPage(); Feedback = $"Generated {await service.GenerateHallTicketsAsync(HallTicketsInput.ExamId.Value, default)} new hall tickets."; return RedirectToPage(); }
    public async Task<IActionResult> OnPostRubricAsync() { if (!Rubric.ExamScheduleId.HasValue) return RedirectToPage(); db.MarkRubrics.Add(new MarkRubric { ExamScheduleId = Rubric.ExamScheduleId.Value, Name = Rubric.Name.Trim() }); await db.SaveChangesAsync(); Feedback = "Rubric created."; return RedirectToPage(); }
    public async Task<IActionResult> OnPostCriterionAsync() { if (!Criterion.MarkRubricId.HasValue) return RedirectToPage(); db.MarkRubricCriteria.Add(new MarkRubricCriterion { MarkRubricId = Criterion.MarkRubricId.Value, Name = Criterion.Name.Trim(), MaximumMarks = Criterion.MaximumMarks, SortOrder = Criterion.SortOrder }); await db.SaveChangesAsync(); Feedback = "Rubric criterion added."; return RedirectToPage(); }
    public async Task<IActionResult> OnPostRubricScoreAsync() { if (!RubricScore.MarkEntryId.HasValue || !RubricScore.CriterionId.HasValue) return RedirectToPage(); var criterion = await db.MarkRubricCriteria.FindAsync(RubricScore.CriterionId.Value); if (criterion is null || RubricScore.MarksAwarded > criterion.MaximumMarks) { ModelState.AddModelError(string.Empty,"Rubric score exceeds the criterion maximum."); await LoadAsync(); return Page(); } var score = await db.MarkRubricScores.FirstOrDefaultAsync(x=>x.MarkEntryId==RubricScore.MarkEntryId && x.MarkRubricCriterionId==RubricScore.CriterionId); if(score is null) db.MarkRubricScores.Add(new MarkRubricScore{MarkEntryId=RubricScore.MarkEntryId.Value,MarkRubricCriterionId=RubricScore.CriterionId.Value,MarksAwarded=RubricScore.MarksAwarded,Feedback=RubricScore.Feedback}); else {score.MarksAwarded=RubricScore.MarksAwarded;score.Feedback=RubricScore.Feedback;} await db.SaveChangesAsync(); var entry=await db.MarkEntries.Include(x=>x.ExamSchedule).SingleAsync(x=>x.Id==RubricScore.MarkEntryId.Value); var total=await db.MarkRubricScores.Where(x=>x.MarkEntryId==entry.Id).SumAsync(x=>x.MarksAwarded); if(total>entry.ExamSchedule!.MaximumMarks){ModelState.AddModelError(string.Empty,"The rubric total exceeds the schedule maximum marks.");await LoadAsync();return Page();} entry.MarksObtained=total;entry.IsAbsent=false;await db.SaveChangesAsync(); Feedback="Rubric score and mark total saved."; return RedirectToPage(); }
    public async Task<IActionResult> OnPostPreviewMarksAsync() { if (!MarksImport.ExamScheduleId.HasValue || MarksImport.File is null) return RedirectToPage(); if(Path.GetExtension(MarksImport.File.FileName).ToLowerInvariant() != ".xlsx" || MarksImport.File.Length > 10*1024*1024){ModelState.AddModelError(string.Empty,"Upload an .xlsx file no larger than 10 MB.");await LoadAsync();return Page();} await using var stream=MarksImport.File.OpenReadStream(); var batch=await service.PreviewMarksAsync(MarksImport.ExamScheduleId.Value,stream,MarksImport.File.FileName,UserId()!.Value,default); Feedback=$"Preview complete: {batch.ValidRows} valid, {batch.ErrorRows} errors.";return RedirectToPage(); }
    public async Task<IActionResult> OnPostExecuteImportAsync(Guid id){var batch=await service.ExecuteMarksImportAsync(id,UserId()!.Value,default);Feedback=$"Imported {batch.ImportedRows} mark rows.";return RedirectToPage();}
    public async Task<IActionResult> OnPostRequestReviewAsync(){if(!Review.MarkEntryId.HasValue)return RedirectToPage();var mark=await db.MarkEntries.FindAsync(Review.MarkEntryId.Value);if(mark is null)return NotFound();db.ResultReviewRequests.Add(new ResultReviewRequest{MarkEntryId=mark.Id,StudentProfileId=mark.StudentProfileId,Type=Review.Type,Reason=Review.Reason.Trim(),OriginalMarks=mark.MarksObtained,RequestedByUserId=UserId()!.Value});await db.SaveChangesAsync();Feedback="Review request submitted.";return RedirectToPage();}
    public async Task<IActionResult> OnPostReviewRequestAsync(Guid id,ApprovalStatus status,decimal? revisedMarks,string? notes){var request=await db.ResultReviewRequests.Include(x=>x.MarkEntry).SingleAsync(x=>x.Id==id);request.Status=status;request.RevisedMarks=status==ApprovalStatus.Approved?revisedMarks:null;request.ReviewNotes=notes;request.ReviewedByUserId=UserId();request.ReviewedOn=DateTime.UtcNow;if(status==ApprovalStatus.Approved&&revisedMarks.HasValue&&request.MarkEntry is not null)request.MarkEntry.MarksObtained=revisedMarks.Value;await db.SaveChangesAsync();Feedback="Result review completed.";return RedirectToPage();}
    public async Task<IActionResult> OnPostTranscriptAsync(Guid studentId){var transcript=await service.GenerateTranscriptAsync(studentId,default);Feedback=$"Transcript {transcript.TranscriptNumber} generated.";return RedirectToPage(new{studentId});}
    public async Task<IActionResult> OnPostTemplateAsync(){db.ReportCardTemplates.Add(new ReportCardTemplate{BranchId=Template.BranchId,CourseId=Template.CourseId,Name=Template.Name.Trim(),PrimaryColor=Template.PrimaryColor,HeaderText=Template.HeaderText,FooterText=Template.FooterText,ShowRank=Template.ShowRank,ShowGradePoint=Template.ShowGradePoint,ShowAttendance=Template.ShowAttendance,IsDefault=Template.IsDefault});await db.SaveChangesAsync();Feedback="Report-card template saved.";return RedirectToPage();}
    public async Task<IActionResult> OnPostPolicyAsync(){db.QuestionPaperReviewPolicies.Add(new QuestionPaperReviewPolicy{BranchId=Policy.BranchId,Name=Policy.Name.Trim(),RequiredReviewerCount=Policy.RequiredReviewerCount,RequiredApprovalCount=Policy.RequiredApprovalCount,RejectOnAnyRejection=Policy.RejectOnAnyRejection,IsDefault=Policy.IsDefault});await db.SaveChangesAsync();Feedback="Moderation policy saved.";return RedirectToPage();}
    public async Task<IActionResult> OnPostModerateAsync(){if(!Moderation.QuestionPaperId.HasValue)return RedirectToPage();await service.ApplyModerationDecisionAsync(Moderation.QuestionPaperId.Value,UserId()!.Value,Moderation.Decision,Moderation.Notes,default);Feedback="Moderation decision recorded.";return RedirectToPage();}
    public async Task<IActionResult> OnPostReleaseAsync(){if(!Release.QuestionPaperVersionId.HasValue||!Release.ReleasedToUserId.HasValue)return RedirectToPage();var version=await db.QuestionPaperVersions.Include(x=>x.QuestionPaper).SingleOrDefaultAsync(x=>x.Id==Release.QuestionPaperVersionId.Value);if(version?.QuestionPaper?.Status!=ApprovalStatus.Approved&&version?.QuestionPaper?.Status!=ApprovalStatus.Published){ModelState.AddModelError(string.Empty,"Only an approved paper's marking scheme can be released.");await LoadAsync();return Page();}db.MarkingSchemeReleases.Add(new MarkingSchemeRelease{QuestionPaperVersionId=version.Id,ReleasedToUserId=Release.ReleasedToUserId.Value,Status=MarkingSchemeReleaseStatus.Released,ReleasedOn=DateTime.UtcNow,ExpiresOn=Release.ExpiresOn.ToUniversalTime(),ReleasedByUserId=UserId(),Notes=Release.Notes});await db.SaveChangesAsync();Feedback="Marking scheme released securely.";return RedirectToPage();}
    public async Task<IActionResult> OnPostAttendanceAsync(){if(!AttendanceInputModel.ExamScheduleId.HasValue||!AttendanceInputModel.StudentProfileId.HasValue)return RedirectToPage();var record=await db.ExamAttendanceRecords.FirstOrDefaultAsync(x=>x.ExamScheduleId==AttendanceInputModel.ExamScheduleId&&x.StudentProfileId==AttendanceInputModel.StudentProfileId);if(record is null)db.ExamAttendanceRecords.Add(new ExamAttendanceRecord{ExamScheduleId=AttendanceInputModel.ExamScheduleId.Value,StudentProfileId=AttendanceInputModel.StudentProfileId.Value,Status=AttendanceInputModel.Status,Notes=AttendanceInputModel.Notes,RecordedByUserId=UserId()});else{record.Status=AttendanceInputModel.Status;record.Notes=AttendanceInputModel.Notes;}var mark=await db.MarkEntries.FirstOrDefaultAsync(x=>x.ExamScheduleId==AttendanceInputModel.ExamScheduleId&&x.StudentProfileId==AttendanceInputModel.StudentProfileId);if(mark is not null)mark.IsAbsent=AttendanceInputModel.Status is ExamAttendanceStatus.Absent or ExamAttendanceStatus.Expelled;await db.SaveChangesAsync();Feedback="Exam attendance saved and reconciled with marks.";return RedirectToPage();}
    public IActionResult OnGetMarksTemplate()=>File(service.BuildMarksTemplate(),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet","marks-import-template.xlsx");
    public async Task<IActionResult> OnPostMalpracticeAsync(){if(!MalpracticeInputModel.ExamScheduleId.HasValue||!MalpracticeInputModel.StudentProfileId.HasValue)return RedirectToPage();db.ExamMalpracticeRecords.Add(new ExamMalpracticeRecord{ExamScheduleId=MalpracticeInputModel.ExamScheduleId.Value,StudentProfileId=MalpracticeInputModel.StudentProfileId.Value,Severity=MalpracticeInputModel.Severity,Description=MalpracticeInputModel.Description.Trim(),ReportedByUserId=UserId()});await db.SaveChangesAsync();Feedback="Malpractice case recorded.";return RedirectToPage();}
    public async Task<IActionResult> OnPostExternalRuleAsync(){if(!ExternalRule.GradingSchemeId.HasValue)return RedirectToPage();db.ExternalGradingRules.Add(new ExternalGradingRule{GradingSchemeId=ExternalRule.GradingSchemeId.Value,AuthorityName=ExternalRule.AuthorityName.Trim(),AuthorityCode=ExternalRule.AuthorityCode,MaximumGraceMarks=ExternalRule.MaximumGraceMarks,MaximumGracePercentage=ExternalRule.MaximumGracePercentage,GraceOnlyForPassing=ExternalRule.GraceOnlyForPassing,ApplyBestOfSubjects=ExternalRule.ApplyBestOfSubjects,BestOfSubjectCount=ExternalRule.BestOfSubjectCount});await db.SaveChangesAsync();Feedback="External grading and grace rule saved.";return RedirectToPage();}
    public async Task<IActionResult> OnGetMarkingSchemeAsync(Guid id){var release=await db.MarkingSchemeReleases.Include(x=>x.QuestionPaperVersion).SingleOrDefaultAsync(x=>x.Id==id);if(release?.QuestionPaperVersion is null||release.Status!=MarkingSchemeReleaseStatus.Released||release.ExpiresOn<DateTime.UtcNow)return NotFound();if(release.ReleasedToUserId!=UserId()&&!User.IsInRole(Roles.SuperAdmin)&&!User.IsInRole(Roles.TenantAdmin)&&!User.IsInRole(Roles.BranchAdmin))return Forbid();return File(System.Text.Encoding.UTF8.GetBytes(release.QuestionPaperVersion.SolutionContentJson),"application/json",$"marking-scheme-v{release.QuestionPaperVersion.VersionNumber}.json");}

    private async Task LoadAsync(){var branches=await branchAccess.FilterBranchesAsync(User,await db.Branches.ToListAsync());var branchIds=branches.Select(x=>x.Id).ToList();Exams=await db.Exams.Where(x=>branchIds.Contains(x.BranchId)).OrderByDescending(x=>x.StartDate).ToListAsync();var examIds=Exams.Select(x=>x.Id).ToList();Schedules=await db.ExamSchedules.Include(x=>x.Exam).Include(x=>x.Subject).Include(x=>x.Section).Where(x=>examIds.Contains(x.ExamId)).OrderByDescending(x=>x.ExamDate).ToListAsync();Students=await db.StudentProfiles.Where(x=>branchIds.Contains(x.BranchId)).OrderBy(x=>x.FirstName).ToListAsync();Papers=await db.QuestionPapers.Where(x=>branchIds.Contains(x.BranchId)).OrderByDescending(x=>x.CreatedOn).ToListAsync();var paperIds=Papers.Select(x=>x.Id).ToList();Versions=await db.QuestionPaperVersions.Where(x=>paperIds.Contains(x.QuestionPaperId)).OrderByDescending(x=>x.VersionNumber).ToListAsync();Reviewers=await db.Users.Where(x=>x.IsActive&&(branchIds.Contains(x.BranchId??Guid.Empty)||x.BranchId==null)).OrderBy(x=>x.FirstName).ToListAsync();Schemes=await db.GradingSchemes.Where(x=>!x.BranchId.HasValue||branchIds.Contains(x.BranchId.Value)).ToListAsync();var scheduleIds=Schedules.Select(x=>x.Id).ToList();Rubrics=await db.MarkRubrics.Where(x=>scheduleIds.Contains(x.ExamScheduleId)).OrderBy(x=>x.Name).ToListAsync();var rubricIds=Rubrics.Select(x=>x.Id).ToList();Criteria=await db.MarkRubricCriteria.Where(x=>rubricIds.Contains(x.MarkRubricId)).OrderBy(x=>x.SortOrder).ToListAsync();Marks=await db.MarkEntries.Include(x=>x.StudentProfile).Where(x=>scheduleIds.Contains(x.ExamScheduleId)).OrderByDescending(x=>x.EnteredOn).Take(200).ToListAsync();Imports=await db.MarksImportBatches.Include(x=>x.Rows).Where(x=>scheduleIds.Contains(x.ExamScheduleId)).OrderByDescending(x=>x.UploadedOn).Take(30).ToListAsync();SeatingPlans=await db.ExamSeatingPlans.Where(x=>scheduleIds.Contains(x.ExamScheduleId)).OrderByDescending(x=>x.GeneratedOn).Take(30).ToListAsync();HallTickets=await db.ExamHallTickets.Where(x=>examIds.Contains(x.ExamId)).OrderByDescending(x=>x.GeneratedOn).Take(100).ToListAsync();Reviews=await db.ResultReviewRequests.Include(x=>x.StudentProfile).Where(x=>scheduleIds.Contains(x.MarkEntry!.ExamScheduleId)).OrderByDescending(x=>x.RequestedOn).Take(100).ToListAsync();Templates=await db.ReportCardTemplates.Where(x=>!x.BranchId.HasValue||branchIds.Contains(x.BranchId.Value)).ToListAsync();Policies=await db.QuestionPaperReviewPolicies.Where(x=>!x.BranchId.HasValue||branchIds.Contains(x.BranchId.Value)).ToListAsync();Releases=await db.MarkingSchemeReleases.Include(x=>x.QuestionPaperVersion).OrderByDescending(x=>x.ReleasedOn).Take(100).ToListAsync();Attendance=await db.ExamAttendanceRecords.Include(x=>x.StudentProfile).Where(x=>scheduleIds.Contains(x.ExamScheduleId)).OrderByDescending(x=>x.RecordedOn).Take(100).ToListAsync();Malpractice=await db.ExamMalpracticeRecords.Include(x=>x.StudentProfile).Where(x=>scheduleIds.Contains(x.ExamScheduleId)).OrderByDescending(x=>x.ReportedOn).Take(100).ToListAsync();ExternalRules=await db.ExternalGradingRules.ToListAsync();if(ComparisonStudentId.HasValue){Comparisons=await db.Results.Include(x=>x.Exam).Include(x=>x.AcademicYear).Where(x=>x.StudentProfileId==ComparisonStudentId&&x.Status==ResultStatus.Published).OrderBy(x=>x.AcademicYear!.StartDate).ThenBy(x=>x.Exam!.StartDate).Select(x=>new ResultComparisonRow(x.Exam!.Name,x.AcademicYear!.Name,x.Percentage,x.Grade,x.IsPassed,x.Rank)).ToListAsync();}}
    private Guid? UserId()=>Guid.TryParse(User.FindFirstValue(ClaimTypes.NameIdentifier),out var id)?id:null;
}
